def max_product(num_str: str, N: int, K: int) -> int:
    """
    Computes the maximum product obtainable by inserting K multiplication signs into a numeric string.

    Parameters
    ----------
    num_str : str
        The numeric string.
    N : int
        Expected length of the numeric string.
    K : int
        Number of multiplication signs to insert.

    Returns
    -------
    int
        The maximum product that can be obtained.
    """
    # Ensure the length used matches the string's actual length
    length = len(num_str)
    if length != N:
        N = length

    if N == 0 or K < 0:
        return 0

    # No multiplication signs -> product is just the integer itself
    if K == 0:
        try:
            return int(num_str)
        except ValueError:
            return 0

    # Impossible to insert more signs than available positions
    if K > N - 1:
        return 0

    # dp[i][k] is the maximum product obtainable from the first i digits with k multiplication signs
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplication signs
    for i in range(1, N + 1):
        try:
            dp[i][0] = int(num_str[:i])
        except ValueError:
            dp[i][0] = 0

    for k in range(1, K + 1):
        # At least k+1 digits are needed to place k multiplication signs
        for i in range(k + 1, N + 1):
            best = 0
            # Try every possible split point j (where the last number starts)
            for j in range(k, i):
                try:
                    val = int(num_str[j:i])
                except ValueError:
                    val = 0
                prod = dp[j][k - 1] * val
                if prod > best:
                    best = prod
            dp[i][k] = best

    return dp[N][K]

