def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    Parameters:
    x0 (int): The desired greatest common divisor.
    y0 (int): The desired least common multiple.

    Returns:
    int: Number of pairs satisfying the constraints.
    """
    if x0 <= 0 or y0 <= 0:
        return 0

    # y0 must be a multiple of x0
    if y0 % x0 != 0:
        return 0

    z = y0 // x0
    count = 0

    for d in range(1, isqrt(z) + 1):
        if z % d == 0:
            a, b = d, z // d
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder and not postorder:
        return ''
    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder strings must have the same length")
    # Build a map for quick lookup of indices in inorder
    index_map = {ch: idx for idx, ch in enumerate(inorder)}

    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start >= in_end or post_start >= post_end:
            return ''
        root = postorder[post_end - 1]
        root_idx = index_map[root]
        # Number of nodes in left subtree
        left_size = root_idx - in_start
        # Recursively build left and right preorders
        left_pre = helper(in_start, root_idx, post_start, post_start + left_size)
        right_pre = helper(root_idx + 1, in_end, post_start + left_size, post_end - 1)
        return root + left_pre + right_pre

    return helper(0, len(inorder), 0, len(postorder))

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    from collections import deque

    # Build mapping from source digit to list of target digits
    rule_map = {}
    for src, tgt in rules:
        if src == tgt:
            continue  # skip redundant rule
        rule_map.setdefault(src, []).append(tgt)

    visited = {n}
    queue = deque([n])

    while queue:
        num = queue.popleft()
        s = str(num)
        for idx, ch in enumerate(s):
            digit = int(ch)
            if digit in rule_map:
                for new_digit in rule_map[digit]:
                    if new_digit == digit:
                        continue
                    new_s = s[:idx] + str(new_digit) + s[idx + 1 :]
                    new_num = int(new_s)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Uses breadth-first search (BFS) to explore all possible transformations.
    The function returns the count of unique numbers that can be generated from the original number,
    including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(rules, list):
        raise ValueError("rules must be a list of tuples")
    # Build mapping from digit to set of possible transformed digits
    rule_map = {}
    for pair in rules:
        if not (isinstance(pair, tuple) and len(pair) == 2):
            raise ValueError("Each rule must be a tuple of two digits")
        x, y = pair
        if not (isinstance(x, int) and isinstance(y, int) and 0 <= x <= 9 and 0 <= y <= 9):
            raise ValueError("Rule digits must be integers between 0 and 9")
        rule_map.setdefault(str(x), set()).add(str(y))

    start_str = str(n)
    from collections import deque
    queue = deque([start_str])
    visited = set([start_str])

    while queue:
        curr = queue.popleft()
        digits = list(curr)
        for idx, d in enumerate(digits):
            if d in rule_map:
                for new_d in rule_map[d]:
                    new_digits = digits.copy()
                    new_digits[idx] = new_d
                    new_num_str = "".join(new_digits)
                    if new_num_str not in visited:
                        visited.add(new_num_str)
                        queue.append(new_num_str)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal
    based on the given statements. A statement that references a day of the week
    is ignored.

    Parameters
    ----------
    scenario : str
        The name of the participant being tested as the potential criminal.
    liar_count : set
        A set of names of participants who are assumed to be liars.
    statements : dict
        A dictionary mapping participant names to lists of their respective statements.
    days_of_week : set
        A set of strings representing the days of the week.

    Returns
    -------
    bool
        True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalise all names to uppercase for case-insensitive comparison
    scenario = scenario.upper()
    liar_set = {name.upper() for name in liar_count}
    # All participants that ever appear as keys or in statements; include scenario too
    participants = {name.upper() for name in statements}
    participants.add(scenario)

    # Prepare day set for quick lookup
    day_set = {day.upper() for day in days_of_week}

    def is_guilty(name: str) -> bool:
        """
        Returns True if the given name matches the criminal scenario.
        """
        return name.upper() == scenario

    # Helper to parse a single statement
    def parse_statement(speaker: str, statement: str):
        """
        Parses a statement and returns a tuple (subject, claims_guilty)
        or None if the statement doesn't fit known patterns or should be ignored.
        """
        stmt = statement.strip()
        # Ignore statements that contain any day of the week
        if any(day in stmt.upper() for day in day_set):
            return None

        # Lowercase for easier matching, keep original case for names
        s_low = stmt.lower()

        # Pattern: "I am guilty." or "I am not guilty."
        if s_low.startswith("i am"):
            if "not guilty" in s_low:
                return (speaker, False)
            elif "guilty" in s_low:
                return (speaker, True)
            else:
                return None  # not a guilt statement

        # Pattern: "<NAME> is guilty." or "<NAME> is not guilty."
        # Find a name present in participants that appears in the statement
        for name in participants:
            # Avoid matching partial words by checking whole word boundaries
            if name in stmt.upper():
                # Ensure the name is a standalone token
                tokens = stmt.upper().split()
                if name in tokens:
                    # Determine if it says "is guilty" or "is not guilty"
                    if f"{name} is guilty" in stmt.upper():
                        return (name, True)
                    if f"{name} is not guilty" in stmt.upper():
                        return (name, False)
        return None

    # Evaluate all statements
    for speaker, stmts in statements.items():
        speaker_up = speaker.upper()
        for s in stmts:
            parsed = parse_statement(speaker_up, s)
            if parsed is None:
                continue  # skip irrelevant statements
            subject, claim_guilt = parsed

            # Determine whether the speaker is a liar or truth-teller
            is_liar = speaker_up in liar_set

            # Expected truth value of the claim
            actual_guilt = is_guilty(subject)

            # If speaker is liar, his claim must be false; if truth-teller, claim must be true
            if is_liar:
                if claim_guilt == actual_guilt:
                    return False  # liar told the truth
            else:
                if claim_guilt != actual_guilt:
                    return False  # truth-teller lied

    return True

