    Returns:
        int: The minimum remaining space in the box.
    """
    try:
        if V <= 0 or n <= 0:
            return max(V, 0)
        # Use only the first n volumes, ignore negative or zero volumes
        items = [v for v in volumes[:n] if v > 0]
        if not items:
            return V
        dp = [0] * (V + 1)
        for vol in items:
            for cap in range(V, vol - 1, -1):
                new_val = dp[cap - vol] + vol
                if new_val > dp[cap]:
                    dp[cap] = new_val
        return V - dp[V]
    except Exception:
        # In case of unexpected errors, fall back to returning the full remaining space
        return V

